// Pair quantities of the D2.1 perception readout (M19-FR-030, FR-031; AWR-04 §15.10.3, ADR-124). Owner: M19. TS port of
// python/awr/sim/perception/quant.py (acoustic_pair, visual_pair, radar_pair and the display probabilities), compared on the
// golden fixture apps/web/tests/m19/quant_cases.json (generated by tests/perception/test_field_golden.py): arrival level and
// margin <= 0.1 dB, angular size and equivalent pixels <= 1 %, radar SNR <= 0.1 dB. The page normally shows the server's
// readings (target/{id}/quant); these functions serve what-if hints (the default-person shell of the legend when no target
// is selected, form previews) with the same formulas. Probabilities are for display only: the discovery decision is the
// deterministic criterion (ADR-099), and P = 0.5 exactly at the criterion boundary.

/** 1/3-octave bands 50 Hz - 10 kHz (nominal centre frequencies; exact centre 1000 * 10^((b - 13)/10)) */
export const BANDS_HZ: readonly number[] = [50, 63, 80, 100, 125, 160, 200, 250, 315, 400, 500, 630, 800, 1000, 1250, 1600, 2000, 2500, 3150, 4000,
  5000, 6300, 8000, 10000]
/** IEC 61672 A-weighting per band (AWR-20 §4.4, 0.1 dB) */
export const A_W: readonly number[] = [-30.2, -26.2, -22.5, -19.1, -16.1, -13.4, -10.9, -8.6, -6.6, -4.8, -3.2, -1.9, -0.8, 0.0, 0.6, 1.0, 1.2, 1.3, 1.2,
  1.0, 0.5, -0.1, -1.1, -2.5]
const OCT_HZ = [63, 125, 250, 500, 1000, 2000, 4000, 8000]
const OCT_ALPHA = [0.1, 0.3, 1.1, 2.8, 5.0, 9.0, 22.9, 76.6]

/** ISO 9613-2 table 2 absorption (20 C, 70 % RH) interpolated in lg(alpha) over log2(f), linear extrapolation at both ends (dB/km) */
export const ALPHA_DB_KM: readonly number[] = BANDS_HZ.map((f) => {
  const x = Math.log2(f)
  const xo = OCT_HZ.map(Math.log2)
  const yo = OCT_ALPHA.map(Math.log10)
  let k = 0
  if (x <= xo[0]) k = 0
  else if (x >= xo[xo.length - 1]) k = xo.length - 2
  else while (k < xo.length - 2 && x > xo[k + 1]) k++
  const y = yo[k] + ((x - xo[k]) * (yo[k + 1] - yo[k])) / (xo[k + 1] - xo[k])
  return 10 ** y
})

export const S_AC_DB = 2.0
export const S_RD_DB = 1.0
export const ARCMIN_PER_RAD = (180 * 60) / Math.PI
export const C_MIN = 0.05
export const K_MOR_LN20 = Math.log(20)
const ELEV45 = (45 * Math.PI) / 180

export function pLogistic(m: number, s: number): number {
  const z = -m / s
  return z > 700 ? 0 : 1 / (1 + Math.exp(z))
}

/** TTPF-shaped visual probability x^E / (1 + x^E), E = 2.7 + 0.7x (P(1) = 0.5) */
export function pVisual(x: number): number {
  if (!(x > 0)) return 0
  if (x > 50) return 1
  const e = 2.7 + 0.7 * x
  const v = x ** e
  return v / (1 + v)
}

export function pAny(ps: readonly number[]): number {
  let q = 1
  for (const p of ps) q *= 1 - p
  return 1 - q
}

/** thr_b = max(L_th, L_bg,b + M_b) + 6(1 - a) - adv (A-weighted band thresholds) */
export function thresholdBands(lBg: readonly number[], masking: readonly number[], hearingThDba: number, alertness: number, advDb: number): number[] {
  return lBg.map((l, b) => Math.max(hearingThDba, l + masking[b]) + 6 * (1 - alertness) - advDb)
}

export interface AcousticQ {
  lpDba: number
  lpBandDb: number
  bandHz: number
  thrDba: number
  lBgDba: number
  marginDb: number
  p: number
}

export interface AcousticPairInput {
  /** unweighted band sound power L_W,b (dB) */
  lwBands: readonly number[]
  rM: number
  gBackDb?: number
  /** A-weighted background band levels (dB(A)) */
  lBgBands: readonly number[]
  masking: readonly number[]
  hearingThDba: number
  alertness: number
  advDb: number
  adjDb?: readonly number[] | null
  /** single-band degenerate variant (AWR-04 §7.3 anchors): own alpha, weighting and centre frequencies */
  alpha?: readonly number[]
  aW?: readonly number[]
  bandsHz?: readonly number[]
}

export function acousticPair(inp: AcousticPairInput): AcousticQ {
  const r = Math.max(inp.rM, 0.1)
  const al = inp.alpha ?? ALPHA_DB_KM
  const aw = inp.aW ?? A_W
  const hz = inp.bandsHz ?? BANDS_HZ
  const g = inp.gBackDb ?? 0
  const thr = thresholdBands(inp.lBgBands, inp.masking, inp.hearingThDba, inp.alertness, inp.advDb)
  let best = -Infinity, bi = 0, sumA = 0, sumBg = 0
  const lp: number[] = []
  for (let b = 0; b < inp.lwBands.length; b++) {
    const l = inp.lwBands[b] - 20 * Math.log10(r) - 11 - (al[b] * r) / 1000 - g
    lp.push(l)
    const w = aw[b] + (inp.adjDb ? inp.adjDb[b] : 0)
    const m = l + w - thr[b]
    if (m > best) { best = m; bi = b }
    sumA += 10 ** ((l + aw[b]) / 10)
    sumBg += 10 ** (inp.lBgBands[b] / 10)
  }
  const wb = aw[bi] + (inp.adjDb ? inp.adjDb[bi] : 0)
  return { lpDba: 10 * Math.log10(sumA), lpBandDb: lp[bi] + wb, bandHz: hz[bi], thrDba: thr[bi], lBgDba: 10 * Math.log10(sumBg), marginDb: best,
    p: pLogistic(best, S_AC_DB) }
}

/** vehicle visual signature: areas top, side (m^2), contrasts, lights */
export interface VisualSig {
  areaTopM2: number
  areaSideM2: number
  contrastSky: number
  contrastGround: number
  lightsOn: boolean
  nightVisibleM: number
}

export interface VisualQ {
  thetaArcmin: number
  dVisM: number
  nEqPx: number | null
  thetaThArcmin: number
  ratio: number
  cApp: number
  p: number
  /** gate passed and theta >= theta_th (night: lights or within night_visible_m): the M18 visual criterion */
  ok: boolean
}

export interface VisualPairInput {
  sig: VisualSig
  rM: number
  /** elevation of the vehicle seen from the target top (rad) */
  elevRad: number
  band: 'day' | 'low' | 'night'
  morM: number
  theta0Arcmin: number
  alertness: number
  acuityArcmin: number | null
  los: boolean | null
  inFov: boolean
}

export function visualPair(inp: VisualPairInput): VisualQ {
  const r = Math.max(inp.rM, 1e-3)
  const e = inp.elevRad
  const d = Math.sqrt(e >= ELEV45 ? inp.sig.areaTopM2 : inp.sig.areaSideM2)
  const th = (inp.theta0Arcmin / ARCMIN_PER_RAD / (0.5 + inp.alertness)) * (inp.band === 'low' ? 2 : 1)
  const sigma = Number.isFinite(inp.morM) && inp.morM > 0 ? K_MOR_LN20 / inp.morM : 0
  const c = Math.abs(e > 0 ? inp.sig.contrastSky : inp.sig.contrastGround)
  const cApp = c * Math.exp(-sigma * r)
  const theta = d / r
  const okAng = inp.band === 'night' ? inp.sig.lightsOn || r <= inp.sig.nightVisibleM : theta >= th
  const gate = inp.los === true && inp.inFov && cApp >= C_MIN
  const p = inp.band === 'night' ? (gate && okAng ? 1 : 0) : gate ? pVisual(theta / th) : 0
  const thetaAm = theta * ARCMIN_PER_RAD
  return { thetaArcmin: thetaAm, dVisM: d, nEqPx: inp.acuityArcmin ? thetaAm / inp.acuityArcmin : null, thetaThArcmin: th * ARCMIN_PER_RAD,
    ratio: theta / th, cApp, p, ok: gate && okAng }
}

export interface RadarRx { snr_ref_db: number; r_ref_m: number; snr_req_db: number; fov_az_deg: number; fov_el_deg: number }

/** gamma_rain = 1.0 * RR^0.7 dB/km (77 GHz class, AWR-20 §6.5) */
export const gammaRainDbKm = (rainMmph: number): number => (rainMmph > 0 ? 1.0 * rainMmph ** 0.7 : 0)

export function radarSnrDb(rx: RadarRx, rcsM2: number, rM: number, rainMmph = 0): number {
  const r = Math.max(rM, 0.1)
  return rx.snr_ref_db + 10 * Math.log10(Math.max(rcsM2, 1e-9)) - 40 * Math.log10(r / rx.r_ref_m) - (2 * gammaRainDbKm(rainMmph) * r) / 1000
}

export function radarPair(rx: RadarRx, rcsM2: number, rM: number, rainMmph: number, inFov: boolean): { snrDb: number; marginDb: number; p: number } {
  const snr = radarSnrDb(rx, rcsM2, rM, rainMmph)
  const m = snr - rx.snr_req_db
  return { snrDb: snr, marginDb: m, p: inFov ? pLogistic(m, S_RD_DB) : 0 }
}

/** default 1/3-octave shape of a vehicle (AWR-20 §4.4; A-weighted energy sum 0 dB) */
export function defaultBandShape(bpfHz: number, tonalDb: number, fPkHz: number): number[] {
  const exact = BANDS_HZ.map((_f, b) => 1000 * 10 ** ((b - 13) / 10))
  const B = exact.map((f) => -(Math.log2(f / fPkHz) ** 2))
  const lin = B.map((x) => 10 ** (x / 10))
  for (let h = 1; h <= 5; h++) {
    const b = bandOf(h * bpfHz)
    if (b >= 0) lin[b] += 10 ** ((B[b] + tonalDb - 3 * (h - 1)) / 10)
  }
  const S = lin.map((v) => 10 * Math.log10(v))
  const c = -10 * Math.log10(S.reduce((acc, s, b) => acc + 10 ** ((s + A_W[b]) / 10), 0))
  return S.map((s) => s + c)
}

export function bandOf(fHz: number): number {
  for (let b = 0; b < 24; b++) {
    const fc = 1000 * 10 ** ((b - 13) / 10)
    if (fHz >= fc * 10 ** -0.05 && fHz < fc * 10 ** 0.05) return b
  }
  return -1
}

/** tonal masking margin per band: -4 dB in the bands of the BPF and its first 4 harmonics, else 0 */
export function tonalMasking(bpfHz: number): number[] {
  const m = new Array<number>(24).fill(0)
  for (let h = 1; h <= 5; h++) {
    const b = bandOf(h * bpfHz)
    if (b >= 0) m[b] = -4
  }
  return m
}

/** effective acoustic radius: per band solve margin = 0 on [1, 5000] m (bisection), largest band (M18 acoustic_radius) */
export function acousticRadius(lwBands: readonly number[], thr: readonly number[], gBackDb = 0, adjDb?: readonly number[] | null): number {
  let best = 0
  for (let b = 0; b < lwBands.length; b++) {
    const w = A_W[b] + (adjDb ? adjDb[b] : 0)
    const f = (r: number): number => lwBands[b] + w - 20 * Math.log10(r) - 11 - (ALPHA_DB_KM[b] * r) / 1000 - gBackDb - thr[b]
    if (f(1) < 0) continue
    if (f(5000) >= 0) return 5000
    let lo = 1, hi = 5000
    for (let i = 0; i < 40; i++) {
      const mid = 0.5 * (lo + hi)
      if (f(mid) >= 0) lo = mid
      else hi = mid
    }
    best = Math.max(best, 0.5 * (lo + hi))
  }
  return best
}
